CONFIGS = {'queue': dict(out='proofs/queue/trace.bend', up='../', imports='import ../../src/queue.bend as Q\nimport ../../spec/queue.bend as S\nimport ../../types/queue.bend as E\nimport ./steps.bend as QS', St='Q.Queue<T>', Mo='List<&2, T>', Obs='E.Obs<T>', Op='E.Op<T>', src='Q', spec='S', abs='QS.abs', inv='QS.inv', steps='QS', PD='-T: Data', PA='T', AA='T', SRUN='T', SREC='T', SPRUN='T', SPCONS='T'), 'binary_heap': dict(out='proofs/binary_heap/trace.bend', up='../', imports='import ../lib/order.bend as O\nimport ../../src/binary_heap.bend as H\nimport ../../spec/binary_heap.bend as S\nimport ../../types/binary_heap.bend as E\nimport ./steps.bend as HS', St='H.Heap<A>', Mo='List<&2, A>', Obs='E.Obs<A>', Op='E.Op<A>', src='H', spec='S', abs='HS.abs', inv='HS.inv', steps='HS', PD='~A: Data, ~cmp: A -> A -> Cmp, ~o: O.Order(~A, ~cmp)', PA='~A, ~cmp, ~o', AA='~A, ~cmp', SRUN='~A, ~cmp', SREC='A', SPRUN='~A, ~cmp', SPCONS='A'), 'balanced_search_tree': dict(out='proofs/balanced_search_tree/trace.bend', up='../', imports='import ../lib/order.bend as O\nimport ../../src/balanced_search_tree.bend as B\nimport ../../spec/balanced_search_tree.bend as S\nimport ../../types/balanced_search_tree.bend as E\nimport ./steps.bend as ST', St='B.OrdMap<K, V>', Mo='List<&2, E.Entry<K, V>>', Obs='E.Obs<K, V>', Op='E.Op<K, V>', src='B', spec='S', abs='ST.abs', inv='ST.inv', steps='ST', PD='~K: Data, ~cmp: K -> K -> Cmp, ~o: O.Order(~K, ~cmp), -V: Data', PA='~K, ~cmp, ~o, V', AA='~K, ~cmp, V', SRUN='~K, ~cmp, V', SREC='K, V', SPRUN='~K, ~cmp, V', SPCONS='K, V'), 'union_find': dict(out='proofs/union_find/trace.bend', up='../', imports='import ../../src/union_find.bend as U\nimport ../../spec/union_find.bend as S\nimport ../../types/union_find.bend as E\nimport ./steps.bend as ST', St='U.UnionFind', Mo='List<&2, Nat>', Obs='E.Obs', Op='E.Op', src='U', spec='S', abs='ST.abs', inv='ST.inv', steps='ST', PD='', PA='', AA='', SRUN='', SREC='', SPRUN='', SPCONS=''), 'segment_tree': dict(out='proofs/segment_tree/trace.bend', up='../', imports='import ../../src/segment_tree.bend as T\nimport ../../spec/segment_tree.bend as S\nimport ../../types/segment_tree.bend as E\nimport ./steps.bend as ST', St='T.SegTree', Mo='List<&2, U32>', Obs='E.Obs', Op='E.Op', src='T', spec='S', abs='ST.abs', inv='ST.inv', steps='ST', PD='', PA='', AA='', SRUN='', SREC='', SPRUN='', SPCONS='')}

def main():
    name = sys.argv[1]
    c = dict(CONFIGS[name])
    out = c.pop('out')
    text = TEMPLATE.format(name=name, **c)
    text = text.replace('(, ', '(')
    p = ROOT / out
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text)
    print('wrote', out)
if __name__ == '__main__':
    main()
